const projects = $input.first().json || [];
const candidates = $input.item(1).json || [];
const submissions = $input.item(2).json || [];

const now = new Date();
const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
const startOfWeek = new Date(now.setDate(now.getDate() - now.getDay()));

// Overall KPIs
const totalProjects = projects.length;
const activeProjects = projects.filter(p => p.status === 'ACTIVE').length;
const filledProjects = projects.filter(p => p.status === 'FILLED').length;

const totalCandidates = candidates.length;
const newCandidatesThisMonth = candidates.filter(c => new Date(c.created_at) >= startOfMonth).length;
const newCandidatesThisWeek = candidates.filter(c => new Date(c.created_at) >= startOfWeek).length;

// Submission KPIs
const totalSubmissions = submissions.length;
const submissionsThisMonth = submissions.filter(s => new Date(s.created_at) >= startOfMonth).length;
const submissionsThisWeek = submissions.filter(s => new Date(s.created_at) >= startOfWeek).length;

// Status breakdown
const statusCounts = submissions.reduce((acc, s) => {
  acc[s.status] = (acc[s.status] || 0) + 1;
  return acc;
}, {});

// Conversion metrics
const interviewStage = submissions.filter(s => s.status === 'INTERVIEW').length;
const offerStage = submissions.filter(s => s.status === 'OFFER').length;
const hiredCount = submissions.filter(s => s.status === 'HIRED').length;
const rejectedCount = submissions.filter(s => s.status === 'REJECTED').length;

// Time-to-hire calculation (for hired candidates)
const hiredSubmissions = submissions.filter(s => s.status === 'HIRED');
const avgTimeToHire = hiredSubmissions.length > 0 
  ? hiredSubmissions.reduce((acc, s) => {
      const days = Math.floor((new Date(s.updated_at) - new Date(s.created_at)) / (1000 * 60 * 60 * 24));
      return acc + days;
    }, 0) / hiredSubmissions.length
  : 0;

// Conversion rates
const submissionToInterviewRate = totalSubmissions > 0 ? ((interviewStage / totalSubmissions) * 100).toFixed(1) : '0.0';
const interviewToOfferRate = interviewStage > 0 ? ((offerStage / interviewStage) * 100).toFixed(1) : '0.0';
const offerToHireRate = offerStage > 0 ? ((hiredCount / offerStage) * 100).toFixed(1) : '0.0';
const overallHireRate = totalSubmissions > 0 ? ((hiredCount / totalSubmissions) * 100).toFixed(1) : '0.0';

// Fill rate
const fillRate = totalProjects > 0 ? ((filledProjects / totalProjects) * 100).toFixed(1) : '0.0';

return [{
  json: {
    date: new Date().toISOString().split('T')[0],
    timestamp: new Date().toISOString(),

    // Project KPIs
    total_projects: totalProjects,
    active_projects: activeProjects,
    filled_projects: filledProjects,
    fill_rate: fillRate + '%',

    // Candidate KPIs
    total_candidates: totalCandidates,
    new_candidates_month: newCandidatesThisMonth,
    new_candidates_week: newCandidatesThisWeek,

    // Submission KPIs
    total_submissions: totalSubmissions,
    submissions_month: submissionsThisMonth,
    submissions_week: submissionsThisWeek,

    // Pipeline Status
    identified: statusCounts.IDENTIFIED || 0,
    qualified: statusCounts.QUALIFIED || 0,
    submitted: statusCounts.SUBMITTED || 0,
    interview: interviewStage,
    offer: offerStage,
    hired: hiredCount,
    rejected: rejectedCount,

    // Conversion Metrics
    submission_to_interview: submissionToInterviewRate + '%',
    interview_to_offer: interviewToOfferRate + '%',
    offer_to_hire: offerToHireRate + '%',
    overall_hire_rate: overallHireRate + '%',

    // Time Metrics
    avg_time_to_hire_days: Math.round(avgTimeToHire),

    // Health Score (simple calculation)
    health_score: Math.min(100, Math.round(
      (activeProjects * 2) + 
      (newCandidatesThisWeek * 1.5) + 
      (submissionsThisWeek * 3) + 
      (parseFloat(overallHireRate) * 2)
    ))
  }
}];
